<template>
  <div>
    <h1>Cloudinary File Upload</h1>
    <input type="file" accept="image/*, application/pdf" @change="onFileSelected" />
    <button @click="uploadFile">Upload File</button>
    <div v-if="uploadResult">
      <h3>Uploaded File</h3>
      <!-- PDF Thumbnail -->
      <div v-if="uploadResult.format === 'pdf'">
        <img :src="pdfThumbnailUrl" alt="PDF Thumbnail" @click="expandPdf" style="width: 100px; cursor: pointer;" />
      </div>
      <!-- Image Preview -->
      <div v-if="uploadResult.format !== 'pdf'">
        <img :src="uploadResult.secure_url" alt="Uploaded Image" style="width: 100px; height: auto;" />
      </div>
      <!-- Full PDF Viewer -->
      <div v-if="showPdf" style="margin-top: 20px;">
        <iframe :src="uploadResult.secure_url" width="100%" height="600px"></iframe>
        <button @click="closePdf">Close PDF</button>
      </div>
      <button @click="removeFile">Remove File</button>
      <h3>Optimized URL</h3>
      <a :href="optimizedUrl" target="_blank">{{ optimizedUrl }}</a>
      <h3>Auto-Cropped URL</h3>
      <a :href="autoCropUrl" target="_blank">{{ autoCropUrl }}</a>
    </div>
  </div>
</template>

<script>
import { Cloudinary } from 'cloudinary-core'
import { getDocument } from 'pdfjs-dist/webpack'

export default {
  name: 'CloudinaryUploader',
  emits: ['upload-success'],
  data() {
    return {
      selectedFile: null,
      uploadResult: null,
      optimizedUrl: '',
      autoCropUrl: '',
      showPdf: false,
      pdfThumbnailUrl: '',
    }
  },
  methods: {
    onFileSelected(event) {
      this.selectedFile = event.target.files[0]
    },
    async uploadFile() {
      if (!this.selectedFile) {
        alert('Please select a file first!')
        return
      }

      const cloudinary = new Cloudinary({ cloud_name: 'alvin-tan' })

      try {
        const formData = new FormData()
        formData.append('file', this.selectedFile)
        formData.append('upload_preset', 'telco_unifi')

        const response = await fetch('https://api.cloudinary.com/v1_1/alvin-tan/auto/upload', {
          method: 'POST',
          body: formData,
        })
        const result = await response.json()
        if (!response.ok) throw new Error(result.error?.message || 'Upload failed')

        this.uploadResult = result
        this.$emit('upload-success', result)

        if (result.format === 'jpg' || result.format === 'png') {
          this.optimizedUrl = cloudinary.url(result.public_id, {
            fetch_format: 'auto',
            quality: 'auto',
          })
          this.autoCropUrl = cloudinary.url(result.public_id, {
            crop: 'fill',
            gravity: 'auto',
            width: 500,
            height: 500,
          })
        }

        if (result.format === 'pdf') {
          await this.generatePdfThumbnail(result.secure_url)
        }

        console.log('Upload Result:', result)
      } catch (error) {
        console.error('Upload error:', error)
        alert('Upload error: ' + error.message)
      }
    },
    async generatePdfThumbnail(pdfUrl) {
      try {
        const loadingTask = getDocument(pdfUrl)
        const pdf = await loadingTask.promise
        const page = await pdf.getPage(1)
        const viewport = page.getViewport({ scale: 0.2 })
        const canvas = document.createElement('canvas')
        const context = canvas.getContext('2d')

        canvas.height = viewport.height
        canvas.width = viewport.width

        await page.render({ canvasContext: context, viewport: viewport }).promise
        this.pdfThumbnailUrl = canvas.toDataURL()
      } catch (error) {
        console.error('PDF thumbnail error:', error)
      }
    },
    expandPdf() {
      this.showPdf = true
    },
    closePdf() {
      this.showPdf = false
    },
    async removeFile() {
      if (!this.uploadResult) {
        alert('No file uploaded to remove!')
        return
      }

      // Note: This won’t work client-side without a proper signature
      alert('Remove File requires server-side signature generation. Using CardDetailsDialog.vue’s deletion instead.')
      this.uploadResult = null
      this.optimizedUrl = ''
      this.autoCropUrl = ''
      this.pdfThumbnailUrl = ''
    },
  },
}
</script>

<style scoped>
img {
  display: block;
  margin-top: 10px;
}
button {
  margin: 10px 0;
  padding: 5px 10px;
  background-color: #007bff;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}
button:hover {
  background-color: #0056b3;
}
</style>